const url = $json.website_url.replace(/\/$/, '');
const paths = [
  '/sitemap.xml', '/site-map.xml', '/sitemap_index.xml', '/sitemap-index.xml',
  '/sitemap.json', '/sitemap-posts.xml', '/sitemap-pages.xml', '/sitemap-blog.xml',
  '/sitemap-category.xml', '/sitemap-image.xml', '/sitemap-video.xml'
];
return paths.map(path => ({ json: { sitemap_url: url + path, website_url: url } }));

const results = $input.all();
const urls = new Set();
const detected = [];
results.forEach(r => {
  if (r.json.statusCode === 200 && r.json.body) {
    detected.push(r.json.url || r.pairedItem.json.sitemap_url);
    const body = typeof r.json.body === 'string' ? r.json.body : JSON.stringify(r.json.body);
    const matches = body.match(/<loc>(.*?)<\/loc>/g);
    if (matches) {
      matches.forEach(m => {
        const u = m.replace(/<\/?[^>]+(>|$)/g, "").trim();
        if (u.startsWith('http')) urls.add(u);
      });
    } else {
       const urlMatches = body.match(/"(https?:\/\/[^" ]+)"/g);
       if (urlMatches) urlMatches.forEach(m => urls.add(m.replace(/"/g, '')));
    }
  }
});
return { urls: Array.from(urls), detected_sitemaps: detected.join(', ') || 'No sitemap detected' };

const html = $json.body || '';
const websiteUrl = $node["Input URL"].json.website_url;
const urls = new Set();
const linkRegex = /href="(https?:\/\/|\/)(.*?)"/g;
let match;
while ((match = linkRegex.exec(html)) !== null) {
  let href = match[1] + match[2];
  if (href.startsWith('/')) href = new URL(websiteUrl).origin + href;
  if (href.startsWith(websiteUrl)) urls.add(href);
}
urls.add(websiteUrl);
return { urls: Array.from(urls), detected_sitemaps: 'No sitemap detected' };

const url = $json.url;
const startTime = Date.now();
let response;
try {
  response = await $httpRequest({
    url: url,
    method: 'GET',
    ignoreSslErrors: true,
    returnFullResponse: true,
    failOnStatusCode: false
  });
} catch (e) {
  response = { body: '', headers: {}, statusCode: 0 };
}
const endTime = Date.now();
return {
  body: response.body,
  headers: response.headers,
  statusCode: response.statusCode,
  responseTime: endTime - startTime
};

if ($index > 0) return [];

const allItems = $input.all();
const titles = new Map();
const results = [];
const urlCounts = { page: 0, blog: 0, post: 0, category: 0, image: 0, video: 0 };

allItems.forEach(item => {
  const html = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body) || '';
  const headers = item.json.headers || {};
  const url = item.pairedItem.json.url;
  const websiteUrl = item.pairedItem.json.website_url;
  const sitemaps = item.pairedItem.json.detected_sitemaps;
  const respTime = item.json.responseTime;

  let category = 'page';
  if (url.match(/\.(jpg|jpeg|png|gif|webp)$/i)) category = 'image';
  else if (url.match(/\.(mp4|webm|ogg)$/i)) category = 'video';
  else if (url.includes('/blog/')) category = 'blog';
  else if (url.includes('/post/')) category = 'post';
  else if (url.includes('/category/')) category = 'category';
  urlCounts[category]++;

  const title = (html.match(/<title>(.*?)<\/title>/i) || ['', ''])[1].trim();
  const h1Match = html.match(/<h1.*?>(.*?)<\/h1>/is);
  const h1 = h1Match ? h1Match[1].replace(/<[^>]+>/g, '').trim() : '';
  const h2 = [...html.matchAll(/<h2.*?>(.*?)<\/h2>/is)].map(m => m[1].replace(/<[^>]+>/g, '').trim()).slice(0, 3).join(', ');
  const metaDesc = (html.match(/<meta\s+[^>]*name=["']description["'][^>]*content=["'](.*?)["']/i) || 
                  html.match(/<meta\s+[^>]*content=["'](.*?)["'][^>]*name=["']description["']/i) || 
                  ['', ''])[1];

  const imgTags = [...html.matchAll(/<img\s+([^>]*?)>/gi)];
  const missingAltCount = imgTags.filter(t => !t[1].toLowerCase().includes('alt=')).length;

  const links = [...html.matchAll(/href=["'](https?:\/\/|\/)(.*?)["']/gi)];
  const internal = links.filter(m => (m[1]+m[2]).startsWith('/') || (m[1]+m[2]).startsWith(websiteUrl)).length;
  const external = links.length - internal;

  const jsonLdMatch = html.match(/<script\s+type=["']application\/ld\+json["']>(.*?)<\/script>/is);
  const jsonLd = jsonLdMatch ? jsonLdMatch[1].trim() : '';
  let schemaTypes = '';
  if (jsonLd) {
    try { 
      const p = JSON.parse(jsonLd);
      schemaTypes = p['@type'] || (Array.isArray(p) ? p.map(x => x['@type']).join(', ') : '');
    } catch(e) {}
  }

  const secHeaders = [
    'strict-transport-security', 'content-security-policy', 'cross-origin-embedder-policy', 
    'cross-origin-opener-policy', 'cross-origin-resource-policy', 'permissions-policy', 
    'referrer-policy', 'x-content-type-options', 'x-frame-options', 'x-xss-protection',
    'x-permitted-cross-domain-policies'
  ];
  let score = 0;
  const secObj = {};
  secHeaders.forEach(h => {
    const val = headers[h.toLowerCase()] ? 'Yes' : 'No';
    secObj[h.replace(/-/g, '_')] = val;
    if (val === 'Yes') score++;
  });

  const perfLabel = respTime < 500 ? 'fast' : (respTime < 1500 ? 'average' : 'slow');
  const isJsHeavy = /id="(__next|root|app)"/.test(html) || (html.match(/<script/g) || []).length > (html.match(/<p|<div/g) || []).length;

  if (title) titles.set(title, (titles.get(title) || 0) + 1);

  results.push({
    page_url: url,
    url_category: category,
    title,
    h1,
    h2,
    meta_description: metaDesc,
    missing_meta_description: !metaDesc,
    missing_h1: !h1,
    focus_keywords: (title + ' ' + h1).toLowerCase().split(/\W+/).filter(w => w.length > 3).slice(0, 5).join(', '),
    image_count: imgTags.length,
    missing_image_alt_count: missingAltCount,
    internal_links: internal,
    external_links: external,
    schema_detected: !!jsonLd,
    schema_types: schemaTypes,
    full_json_ld: jsonLd,
    response_time_ms: respTime,
    performance: perfLabel,
    ...secObj,
    security_score: `${score}/11`,
    security_evaluation: score > 7 ? 'Security good' : 'Security low',
    site_type: isJsHeavy ? "JavaScript-heavy (React/Next/SPA)" : "Static HTML",
    sitemaps_used: sitemaps
  });
});

const summaryInfo = `Total URLs: ${allItems.length} | Pages: ${urlCounts.page} | Blogs: ${urlCounts.blog} | Posts: ${urlCounts.post} | Categories: ${urlCounts.category} | Images: ${urlCounts.image} | Videos: ${urlCounts.video}`;

return results.map(d => ({
  json: { 
    ...d, 
    site_level_summary: summaryInfo,
    duplicate_title_detection: (d.title && titles.get(d.title) > 1) ? 'True' : 'False' 
  } 
}));
